// Package textconv provides helpers for converting text between character
// encodings and for applying Unicode normalization forms.
//
// Conversions are performed through UTF-8: input bytes are decoded from the
// source encoding, normalized while in UTF-8, and then encoded into the target
// encoding. This mirrors the pipeline used by the textconv command.
package textconv

import (
	"fmt"
	"io"
	"sort"
	"strings"

	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/charmap"
	"golang.org/x/text/encoding/japanese"
	"golang.org/x/text/encoding/korean"
	"golang.org/x/text/encoding/simplifiedchinese"
	"golang.org/x/text/encoding/traditionalchinese"
	"golang.org/x/text/encoding/unicode"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// Form identifies a Unicode normalization form. The zero value, None, leaves
// text unchanged.
type Form int

const (
	None Form = iota
	NFC
	NFD
	NFKC
	NFKD
)

// String returns the standard name of the form.
func (f Form) String() string {
	switch f {
	case NFC:
		return "NFC"
	case NFD:
		return "NFD"
	case NFKC:
		return "NFKC"
	case NFKD:
		return "NFKD"
	default:
		return "None"
	}
}

// ParseForm converts a case-insensitive normalization form name ("NFC", "nfkd",
// "none", ...) into a Form.
func ParseForm(name string) (Form, bool) {
	switch strings.ToUpper(strings.TrimSpace(name)) {
	case "", "NONE":
		return None, true
	case "NFC":
		return NFC, true
	case "NFD":
		return NFD, true
	case "NFKC":
		return NFKC, true
	case "NFKD":
		return NFKD, true
	default:
		return None, false
	}
}

// Normalize returns s normalized using the given form. None is a no-op.
func Normalize(s string, form Form) string {
	switch form {
	case NFC:
		return norm.NFC.String(s)
	case NFD:
		return norm.NFD.String(s)
	case NFKC:
		return norm.NFKC.String(s)
	case NFKD:
		return norm.NFKD.String(s)
	default:
		return s
	}
}

// IsNormalized reports whether s is already in the given normalization form.
// None is always reported as normalized.
func IsNormalized(s string, form Form) bool {
	switch form {
	case NFC:
		return norm.NFC.IsNormalString(s)
	case NFD:
		return norm.NFD.IsNormalString(s)
	case NFKC:
		return norm.NFKC.IsNormalString(s)
	case NFKD:
		return norm.NFKD.IsNormalString(s)
	default:
		return true
	}
}

var encodings = map[string]encoding.Encoding{
	"utf-8":         unicode.UTF8,
	"utf-16":        unicode.UTF16(unicode.BigEndian, unicode.UseBOM),
	"utf-16be":      unicode.UTF16(unicode.BigEndian, unicode.IgnoreBOM),
	"utf-16le":      unicode.UTF16(unicode.LittleEndian, unicode.IgnoreBOM),
	"us-ascii":      charmap.USASCII,
	"iso-8859-1":    charmap.ISO8859_1,
	"iso-8859-2":    charmap.ISO8859_2,
	"iso-8859-15":   charmap.ISO8859_15,
	"windows-1252":  charmap.Windows1252,
	"koi8-r":        charmap.KOI8R,
	"shift_jis":     japanese.ShiftJIS,
	"euc-jp":        japanese.EUCJP,
	"iso-2022-jp":   japanese.ISO2022JP,
	"euc-kr":        korean.EUCKR,
	"gbk":           simplifiedchinese.GBK,
	"gb18030":       simplifiedchinese.GB18030,
	"hz-gb-2312":    simplifiedchinese.HZGB2312,
	"big5":          traditionalchinese.Big5,
}

var aliases = map[string]string{
	"utf8":       "utf-8",
	"utf16":      "utf-16",
	"utf16be":    "utf-16be",
	"utf16le":    "utf-16le",
	"ascii":      "us-ascii",
	"latin1":     "iso-8859-1",
	"latin-1":    "iso-8859-1",
	"cp1252":     "windows-1252",
	"sjis":       "shift_jis",
	"shift-jis":  "shift_jis",
	"cp932":      "shift_jis",
	"eucjp":      "euc-jp",
	"euckr":      "euc-kr",
	"cp949":      "euc-kr",
	"gb2312":     "gbk",
	"chinese":    "gbk",
	"big-5":      "big5",
}

// Lookup resolves a case-insensitive encoding name or alias to an encoding.
func Lookup(name string) (encoding.Encoding, bool) {
	key := strings.ToLower(strings.TrimSpace(name))
	if canonical, ok := aliases[key]; ok {
		key = canonical
	}
	enc, ok := encodings[key]
	return enc, ok
}

// Encodings returns the sorted list of canonical encoding names understood by
// Lookup.
func Encodings() []string {
	names := make([]string, 0, len(encodings))
	for name := range encodings {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Decode interprets data as text in the from encoding and returns it as UTF-8.
// A nil encoding is treated as UTF-8.
func Decode(data []byte, from encoding.Encoding) (string, error) {
	if from == nil || from == encoding.Nop {
		return string(data), nil
	}
	out, _, err := transform.Bytes(from.NewDecoder(), data)
	if err != nil {
		return "", fmt.Errorf("decode: %w", err)
	}
	return string(out), nil
}

// Encode converts the UTF-8 string s into the to encoding. A nil encoding is
// treated as UTF-8.
func Encode(s string, to encoding.Encoding) ([]byte, error) {
	if to == nil || to == encoding.Nop {
		return []byte(s), nil
	}
	out, _, err := transform.Bytes(to.NewEncoder(), []byte(s))
	if err != nil {
		return nil, fmt.Errorf("encode: %w", err)
	}
	return out, nil
}

// Convert decodes data from the from encoding, normalizes the resulting text
// using form, and encodes it into the to encoding. The result is always valid
// for the target encoding.
func Convert(data []byte, from, to encoding.Encoding, form Form) ([]byte, error) {
	decoded, err := Decode(data, from)
	if err != nil {
		return nil, err
	}
	return Encode(Normalize(decoded, form), to)
}

// ConvertString is like Convert but takes and returns strings.
func ConvertString(s string, from, to encoding.Encoding, form Form) (string, error) {
	out, err := Convert([]byte(s), from, to, form)
	if err != nil {
		return "", err
	}
	return string(out), nil
}

// NewReader returns a reader that decodes r from the from encoding into UTF-8
// and applies the given normalization form.
func NewReader(r io.Reader, from encoding.Encoding, form Form) io.Reader {
	var t transform.Transformer
	if from != nil && from != encoding.Nop {
		t = from.NewDecoder()
	}
	if form != None {
		t = transform.Chain(t, form.transformer())
	}
	if t == nil {
		return r
	}
	return transform.NewReader(r, t)
}

// NewWriter returns a writer that encodes UTF-8 written to it into the to
// encoding. The caller is responsible for closing the returned WriteCloser.
func NewWriter(w io.Writer, to encoding.Encoding) io.WriteCloser {
	if to == nil || to == encoding.Nop {
		return nopWriteCloser{w}
	}
	return transform.NewWriter(w, to.NewEncoder())
}

// transformer returns the streaming transformer for the form. None is handled
// by callers and must not reach this method.
func (f Form) transformer() transform.Transformer {
	switch f {
	case NFC:
		return norm.NFC
	case NFD:
		return norm.NFD
	case NFKC:
		return norm.NFKC
	case NFKD:
		return norm.NFKD
	default:
		return nil
	}
}

type nopWriteCloser struct {
	io.Writer
}

func (nopWriteCloser) Close() error { return nil }

// Command textconv converts text between character encodings and applies a
// Unicode normalization form.
//
// Usage:
//
//	textconv -from Shift_JIS -to UTF-8 -form NFC [file]
//
// With no file, textconv reads standard input. Use -list to print the
// supported encodings.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"textconv"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "textconv:", err)
		os.Exit(1)
	}
}

func run() error {
	var (
		fromName = flag.String("from", "utf-8", "source encoding")
		toName   = flag.String("to", "utf-8", "target encoding")
		formName = flag.String("form", "NFC", "normalization form: none, NFC, NFD, NFKC or NFKD")
		list     = flag.Bool("list", false, "list supported encodings and exit")
	)
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "Usage: %s [flags] [file]\n\nFlags:\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	if *list {
		for _, name := range textconv.Encodings() {
			fmt.Println(name)
		}
		return nil
	}

	from, ok := textconv.Lookup(*fromName)
	if !ok {
		return fmt.Errorf("unknown source encoding %q (try -list)", *fromName)
	}
	to, ok := textconv.Lookup(*toName)
	if !ok {
		return fmt.Errorf("unknown target encoding %q (try -list)", *toName)
	}
	form, ok := textconv.ParseForm(*formName)
	if !ok {
		return fmt.Errorf("unknown normalization form %q", *formName)
	}

	in := io.Reader(os.Stdin)
	switch args := flag.Args(); len(args) {
	case 0:
		// keep stdin
	case 1:
		f, err := os.Open(args[0])
		if err != nil {
			return err
		}
		defer f.Close()
		in = f
	default:
		return fmt.Errorf("expected at most one input file, got %d", len(args))
	}

	data, err := io.ReadAll(in)
	if err != nil {
		return err
	}
	out, err := textconv.Convert(data, from, to, form)
	if err != nil {
		return err
	}
	_, err = os.Stdout.Write(out)
	return err
}

package textconv

import (
	"bytes"
	"io"
	"strings"
	"testing"

	"golang.org/x/text/encoding/charmap"
	"golang.org/x/text/encoding/japanese"
)

func TestNormalize(t *testing.T) {
	const (
		composed   = "\u00e9"    // é
		decomposed = "e\u0301"    // e + combining acute
		fullWidth  = "\uff21"     // Ａ
		circledOne = "\u2460"     // ①
	)

	tests := []struct {
		name string
		in   string
		form Form
		want string
	}{
		{"nfc composes", decomposed, NFC, composed},
		{"nfd decomposes", composed, NFD, decomposed},
		{"nfkc folds width", fullWidth, NFKC, "A"},
		{"nfkc folds compatibility", circledOne, NFKC, "1"},
		{"nfkd folds and decomposes", "\u00e9", NFKD, decomposed},
		{"none is a no-op", decomposed, None, decomposed},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Normalize(tt.in, tt.form); got != tt.want {
				t.Errorf("Normalize(%q, %v) = %q, want %q", tt.in, tt.form, got, tt.want)
			}
		})
	}
}

func TestIsNormalized(t *testing.T) {
	if !IsNormalized("\u00e9", NFC) {
		t.Error("é should be NFC-normalized")
	}
	if IsNormalized("e\u0301", NFC) {
		t.Error("e+combining acute should not be NFC-normalized")
	}
	if !IsNormalized("e\u0301", NFD) {
		t.Error("e+combining acute should be NFD-normalized")
	}
}

func TestParseForm(t *testing.T) {
	cases := map[string]Form{
		"nfc":  NFC,
		"NFD":  NFD,
		"nfKc": NFKC,
		"":     None,
		" none ": None,
	}
	for name, want := range cases {
		got, ok := ParseForm(name)
		if !ok || got != want {
			t.Errorf("ParseForm(%q) = (%v, %v), want (%v, true)", name, got, ok, want)
		}
	}
	if _, ok := ParseForm("nfx"); ok {
		t.Error("ParseForm(\"nfx\") should not be ok")
	}
}

func TestDecodeLatin1(t *testing.T) {
	got, err := Decode([]byte{'e', 0xe9}, charmap.ISO8859_1)
	if err != nil {
		t.Fatal(err)
	}
	if got != "e\u00e9" {
		t.Errorf("Decode = %q, want %q", got, "e\u00e9")
	}
}

func TestEncodeLatin1(t *testing.T) {
	got, err := Encode("e\u00e9", charmap.ISO8859_1)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, []byte{'e', 0xe9}) {
		t.Errorf("Encode = % x, want 65 e9", got)
	}
}

func TestEncodeUnrepresentableErrors(t *testing.T) {
	if _, err := Encode("\u65e5", charmap.ISO8859_1); err == nil {
		t.Error("encoding Japanese to ISO-8859-1 should fail")
	}
}

func TestShiftJISRoundTrip(t *testing.T) {
	const text = "日本語"
	encoded, err := Encode(text, japanese.ShiftJIS)
	if err != nil {
		t.Fatal(err)
	}
	decoded, err := Decode(encoded, japanese.ShiftJIS)
	if err != nil {
		t.Fatal(err)
	}
	if decoded != text {
		t.Errorf("round trip = %q, want %q", decoded, text)
	}
}

func TestConvertNormalizes(t *testing.T) {
	// Decomposed UTF-8 "é" normalized to NFC and re-encoded as UTF-8.
	got, err := Convert([]byte("e\u0301"), nil, nil, NFC)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != "\u00e9" {
		t.Errorf("Convert = %q, want %q", got, "\u00e9")
	}
}

func TestConvertBetweenEncodings(t *testing.T) {
	// ISO-8859-1 "eé" to UTF-8.
	got, err := Convert([]byte{'e', 0xe9}, charmap.ISO8859_1, nil, NFC)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != "e\u00e9" {
		t.Errorf("Convert = %q, want %q", got, "e\u00e9")
	}
}

func TestLookup(t *testing.T) {
	for _, name := range []string{"UTF-8", "utf8", "Shift_JIS", "sjis", "Latin1", "cp1252"} {
		if _, ok := Lookup(name); !ok {
			t.Errorf("Lookup(%q) failed", name)
		}
	}
	if _, ok := Lookup("not-an-encoding"); ok {
		t.Error("Lookup of unknown encoding should fail")
	}
}

func TestEncodingsSorted(t *testing.T) {
	names := Encodings()
	if len(names) == 0 {
		t.Fatal("Encodings returned nothing")
	}
	for i := 1; i < len(names); i++ {
		if names[i-1] >= names[i] {
			t.Fatalf("Encodings not sorted: %q >= %q", names[i-1], names[i])
		}
	}
}

func TestReaderWriter(t *testing.T) {
	r := NewReader(strings.NewReader("e\xe9"), charmap.ISO8859_1, NFC)
	got, err := io.ReadAll(r)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != "e\u00e9" {
		t.Errorf("NewReader = %q, want %q", got, "e\u00e9")
	}

	var buf bytes.Buffer
	w := NewWriter(&buf, charmap.ISO8859_1)
	if _, err := io.WriteString(w, "e\u00e9"); err != nil {
		t.Fatal(err)
	}
	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(buf.Bytes(), []byte{'e', 0xe9}) {
		t.Errorf("NewWriter = % x, want 65 e9", buf.Bytes())
	}
}

